let lastMs=0,engine,player,activeResolve,worker,seq=0,pending=new Map(),cache=new Map(),loading=false;
let selected='de_DE-thorsten-medium';try{selected=localStorage.getItem('wortreise-neural-voice')||selected}catch{}
if(selected==='de_DE-thorsten-high'){try{if(!localStorage.getItem('wortreise-fast-v3')){selected='de_DE-thorsten-medium';localStorage.setItem('wortreise-fast-v3','1');localStorage.setItem('wortreise-neural-voice',selected)}}catch{}}
const announce=message=>document.querySelectorAll('[data-voice-status]').forEach(e=>e.textContent=message);
export function selection(){return selected}
export function choose(value){stopVoice();selected=value;try{localStorage.setItem('wortreise-neural-voice',value)}catch{}document.querySelectorAll('[data-neural-voice]').forEach(e=>e.value=value);announce(value==='device'?'Device voice selected. Quality depends on your installed German voice.':'Voice selected. This voice stays ready between phrases.');}
export function stopVoice(){seq++;player?.pause();if(activeResolve){activeResolve();activeResolve=null}window.speechSynthesis?.cancel();for(let p of pending.values())p.resolve(null);pending.clear();loading=false;worker?.postMessage({type:'cancel'});announce('Ready when you are.');}
function getWorker(){if(worker)return worker;worker=new Worker('voice-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.type==='status'){if(pending.size)announce(data.message);return}let p=pending.get(data.id);if(!p)return;pending.delete(data.id);loading=false;lastMs=data.ms||0;if(data.error){announce("Voice could not start: "+data.error);p.reject(Error(data.error))}else {announce('Speech generated in '+(data.ms/1000).toFixed(2)+'s');p.resolve(data.blob)}};worker.onerror=()=>{loading=false;for(let p of pending.values())p.reject(Error('This browser could not start the neural voice. Try another browser or choose Device voice.'));pending.clear();worker?.terminate();worker=null};return worker}
export async function neuralSpeak(text,rate=1,lang='de-DE'){stopVoice();if(!text.trim())return;const token=seq;if(lang.startsWith('en')||selected==='device'){if(!window.speechSynthesis)throw Error('Device speech is unavailable. Select a neural German voice.');return new Promise(resolve=>{let u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=rate;const candidates=speechSynthesis.getVoices().filter(v=>v.lang.startsWith(lang.slice(0,2)));u.voice=candidates.find(v=>/natural|online|premium|enhanced/i.test(v.name))||candidates[0]||null;u.onend=resolve;u.onerror=resolve;activeResolve=resolve;speechSynthesis.speak(u)})}lastMs=0;const key=selected+'|'+text;let blob=cache.get(key),audioStore,urlKey;try{urlKey=new URL('/__spoken/'+encodeURIComponent(key),location.origin).href;audioStore=await caches.open('wortreise-spoken-v3');if(!blob){const hit=await audioStore.match(urlKey);if(hit)blob=await hit.blob()}}catch{}if(token!==seq)return;if(!blob){announce('Preparing speech… first use sets up this voice; later phrases reuse the engine.');loading=true;blob=await new Promise((resolve,reject)=>{pending.set(token,{resolve,reject});getWorker().postMessage({id:token,text,voiceId:selected})});if(!blob||token!==seq)return;if(audioStore)audioStore.put(urlKey,new Response(blob)).then(async()=>{const keys=await audioStore.keys();if(keys.length>300)await audioStore.delete(keys[0])}).catch(()=>{});cache.set(key,blob);if(cache.size>80)cache.delete(cache.keys().next().value)}if(token!==seq)return;player=new Audio();player.src=URL.createObjectURL(blob);player.playbackRate=rate;player.preservesPitch=true;announce(`${selected.includes('thorsten')?'Thorsten · male':'Kerstin · female'} · ${lastMs?(lastMs/1000).toFixed(2)+'s generation':'instant replay'} · ${rate.toFixed(2)}×`);return new Promise((resolve,reject)=>{const url=player.src;const done=()=>{URL.revokeObjectURL(url);activeResolve=null;resolve()};activeResolve=done;player.onended=done;player.onerror=()=>{done();reject(Error('Audio could not play. Tap Listen again.'))};player.play().catch(()=>{done();announce('Voice ready. Tap Listen again to start playback.');reject(Error('Tap Listen again to allow audio playback after the voice download.'))})})}
export function updateAudioRate(rate){if(player)player.playbackRate=rate}
